  let py = rocq_array::get::<u64>(&rep, y);
  if eqb(px, py) {
    (((rep, nxt), tl), sz)
  } else {
    let tmp = rocq_array::get::<u64>(&sz, py);
    let tmp_1 = rocq_array::get::<u64>(&sz, px);
    if ltb(tmp, tmp_1) {
      merge(px, py, rep, nxt, tl, sz)
    } else {
      merge(py, px, rep, nxt, tl, sz)
    }
  }
